        }
        let sl = &b[rva..rva + sz];
        if st == 3 && sl.len() >= 8 {
            let lo = u32::from_le_bytes(sl[0..4].try_into().unwrap());
            let hi = u32::from_le_bytes(sl[4..8].try_into().unwrap());
            crash = Some((lo, hi));
