use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::Path;

#[derive(Clone)]
struct Group { guid: [u8;16], chrono: u64, rows: Vec<(String,u8)>, anchor: Option<usize> }

fn prior() -> HashMap<String,usize> {
    let source = if Path::new("/app/tidearc/lastgood.rec").is_file() {
        "/app/tidearc/lastgood.rec"
    } else { "/app/kegbay/hide.rec" };
    let mut out = HashMap::new();
    if let Ok(raw) = fs::read_to_string(source) {
        for (i,line) in raw.lines().enumerate() {
            let p: Vec<&str> = line.split_whitespace().collect();
            if p.len() >= 2 { out.entry(p[1].to_string()).or_insert(i); }
        }
    }
    out
}

pub fn rib_c(pairs: &[(String,u64)]) -> Result<Vec<String>,i32> {
    if pairs.is_empty() { return Err(1); }
    let old = prior();
    let mut map: HashMap<[u8;16],Group> = HashMap::new();
    for (path,key) in pairs {
        let m = crate::parse::load(path).map_err(|_| 1)?;
        let name = Path::new(path).file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
        let g = map.entry(m.guid).or_insert(Group { guid:m.guid, chrono:*key, rows:Vec::new(), anchor:None });
        if m.crash.is_some() || g.rows.is_empty() { g.chrono = g.chrono.min(*key); }
        if let Some(&ix) = old.get(&name) { g.anchor = Some(g.anchor.map_or(ix, |v| v.min(ix))); }
        g.rows.push((path.clone(),m.companion));
    }
    let mut groups: Vec<Group> = map.into_values().collect();
    let mut anchored: Vec<Group> = groups.iter().filter(|g| g.anchor.is_some()).cloned().collect();
    let mut fresh: Vec<Group> = groups.drain(..).filter(|g| g.anchor.is_none()).collect();
    anchored.sort_by_key(|g| g.anchor.unwrap());
    fresh.sort_by(|a,b| (a.chrono,a.guid).cmp(&(b.chrono,b.guid)));
    for g in fresh {
        let pos = anchored.iter().position(|x| x.chrono > g.chrono).unwrap_or(anchored.len());
        anchored.insert(pos,g);
    }
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for mut g in anchored {
        g.rows.sort_by(|a,b| {
            let an = Path::new(&a.0).file_name().unwrap().to_string_lossy();
            let bn = Path::new(&b.0).file_name().unwrap().to_string_lossy();
            match (old.get(an.as_ref()),old.get(bn.as_ref())) {
                (Some(x),Some(y)) => x.cmp(y),
                _ => (a.1,an.as_bytes()).cmp(&(b.1,bn.as_bytes())),
            }
        });
        for (p,_) in g.rows { if seen.insert(p.clone()) { out.push(p); } }
    }
    if out.len() != pairs.len() { Err(1) } else { Ok(out) }
}
